# Re-run with: python analysis.py   (from this folder, next to the data file)

import warnings; warnings.filterwarnings("ignore")
import matplotlib; matplotlib.use("Agg")
import pandas as pd
import matplotlib.pyplot as plt

# 1. Load data and parse dates
df = pd.read_csv('data.csv')
df['order_date'] = pd.to_datetime(df['order_date'])

# 2. Filter for August and September 2026
df['month'] = df['order_date'].dt.to_period('M')
df_aug_sep = df[df['month'].isin([pd.Period('2026-08'), pd.Period('2026-09')])].copy()

# 3. Calculate revenue per row
df_aug_sep['revenue'] = df_aug_sep['units'] * df_aug_sep['unit_price'] * (1 - df_aug_sep['discount'])

# 4. Group by category and month, sum revenue
cat_month_rev = df_aug_sep.groupby(['category', 'month'])['revenue'].sum().unstack(fill_value=0)

# Ensure both months are present for all categories
for m in [pd.Period('2026-08'), pd.Period('2026-09')]:
    if m not in cat_month_rev.columns:
        cat_month_rev[m] = 0

cat_month_rev = cat_month_rev[[pd.Period('2026-08'), pd.Period('2026-09')]]

# 5. Compute change and % change
cat_month_rev['Aug_revenue'] = cat_month_rev[pd.Period('2026-08')]
cat_month_rev['Sep_revenue'] = cat_month_rev[pd.Period('2026-09')]
cat_month_rev['change'] = cat_month_rev['Sep_revenue'] - cat_month_rev['Aug_revenue']
cat_month_rev['pct_change'] = (cat_month_rev['change'] / cat_month_rev['Aug_revenue'].replace(0, pd.NA)) * 100

# 6. Identify category with biggest revenue drop
cat_month_rev_sorted = cat_month_rev.sort_values('change')
biggest_drop_cat = cat_month_rev_sorted.index[0]
biggest_drop_row = cat_month_rev_sorted.iloc[0]

# 7. For that category, group by region and month, sum revenue
cat_df = df_aug_sep[df_aug_sep['category'] == biggest_drop_cat]
region_month_rev = cat_df.groupby(['region', 'month'])['revenue'].sum().unstack(fill_value=0)
for m in [pd.Period('2026-08'), pd.Period('2026-09')]:
    if m not in region_month_rev.columns:
        region_month_rev[m] = 0
region_month_rev = region_month_rev[[pd.Period('2026-08'), pd.Period('2026-09')]]
region_month_rev['change'] = region_month_rev[pd.Period('2026-09')] - region_month_rev[pd.Period('2026-08')]

# 8. Compute each region's share (%) of the total category drop
total_drop = region_month_rev['change'].sum()
region_month_rev['share_pct'] = (region_month_rev['change'] / total_drop * 100).round(2)

# 9. Identify region with largest negative change
region_month_rev_sorted = region_month_rev.sort_values('change')
main_region = region_month_rev_sorted.index[0]
main_region_row = region_month_rev_sorted.iloc[0]

# 10. Top products by revenue drop in the main region
main_region_df = cat_df[cat_df['region'] == main_region]
prod_month_rev = main_region_df.groupby(['product', 'month'])['revenue'].sum().unstack(fill_value=0)
for m in [pd.Period('2026-08'), pd.Period('2026-09')]:
    if m not in prod_month_rev.columns:
        prod_month_rev[m] = 0
prod_month_rev = prod_month_rev[[pd.Period('2026-08'), pd.Period('2026-09')]]
prod_month_rev['change'] = prod_month_rev[pd.Period('2026-09')] - prod_month_rev[pd.Period('2026-08')]
prod_month_rev_sorted = prod_month_rev.sort_values('change')

# 11. Print all required numbers with clear labels
print("REVENUE BY CATEGORY (AUG 2026 vs SEP 2026):")
for cat, row in cat_month_rev.iterrows():
    aug = row['Aug_revenue']
    sep = row['Sep_revenue']
    change = row['change']
    pct = row['pct_change']
    print(f"{cat}: Aug Rs {int(aug):,} ({aug/1e5:.2f} L), Sep Rs {int(sep):,} ({sep/1e5:.2f} L), Change Rs {int(change):,} ({change/1e5:.2f} L), % Change {pct:.2f}%")

print("\nCATEGORY WITH BIGGEST REVENUE DROP:")
print(f"Category: {biggest_drop_cat}")
print(f"Aug Revenue: Rs {int(biggest_drop_row['Aug_revenue']):,} ({biggest_drop_row['Aug_revenue']/1e5:.2f} L)")
print(f"Sep Revenue: Rs {int(biggest_drop_row['Sep_revenue']):,} ({biggest_drop_row['Sep_revenue']/1e5:.2f} L)")
print(f"Change: Rs {int(biggest_drop_row['change']):,} ({biggest_drop_row['change']/1e5:.2f} L)")
print(f"% Change: {biggest_drop_row['pct_change']:.2f}%")

print("\nREGION-WISE REVENUE CHANGE FOR THIS CATEGORY:")
for region, row in region_month_rev.iterrows():
    aug = row[pd.Period('2026-08')]
    sep = row[pd.Period('2026-09')]
    change = row['change']
    share = row['share_pct']
    print(f"{region}: Aug Rs {int(aug):,} ({aug/1e5:.2f} L), Sep Rs {int(sep):,} ({sep/1e5:.2f} L), Change Rs {int(change):,} ({change/1e5:.2f} L), Share of drop: {share:.2f}%")

print(f"\nREGION CAUSING MOST OF THE DROP: {main_region}")
print(f"Change: Rs {int(main_region_row['change']):,} ({main_region_row['change']/1e5:.2f} L), Share: {main_region_row['share_pct']:.2f}%")

print("\nTOP PRODUCTS BY REVENUE DROP IN MAIN REGION:")
for prod, row in prod_month_rev_sorted.iterrows():
    aug = row[pd.Period('2026-08')]
    sep = row[pd.Period('2026-09')]
    change = row['change']
    print(f"{prod}: Aug Rs {int(aug):,} ({aug/1e5:.2f} L), Sep Rs {int(sep):,} ({sep/1e5:.2f} L), Change Rs {int(change):,} ({change/1e5:.2f} L)")

# 12. Charts

# Bar chart: Revenue by category for August and September
fig, ax = plt.subplots(figsize=(8,5))
cat_month_rev_plot = cat_month_rev[['Aug_revenue', 'Sep_revenue']].sort_values('Aug_revenue', ascending=False)
cat_month_rev_plot[['Aug_revenue', 'Sep_revenue']].plot(kind='bar', ax=ax)
ax.set_title("Revenue by Category: Aug vs Sep 2026")
ax.set_xlabel("Category")
ax.set_ylabel("Revenue (Rs lakh)")
ax.legend(['Aug 2026', 'Sep 2026'])
plt.tight_layout()
plt.savefig("category_revenue_aug_sep.png", dpi=120)
plt.close()

# Bar chart: Revenue change by region for the category with the biggest drop
fig, ax = plt.subplots(figsize=(7,4))
region_month_rev_plot = region_month_rev.sort_values('change')
region_month_rev_plot['change_lakh'] = region_month_rev_plot['change'] / 1e5
region_month_rev_plot['change_lakh'].plot(kind='bar', ax=ax, color='salmon')
ax.set_title(f"Revenue Change by Region for {biggest_drop_cat} (Sep vs Aug 2026)")
ax.set_xlabel("Region")
ax.set_ylabel("Revenue Change (Rs lakh)")
plt.tight_layout()
plt.savefig("region_revenue_change_biggest_drop_category.png", dpi=120)
plt.close()

# Bar chart: Top products by revenue drop in the main region
fig, ax = plt.subplots(figsize=(9,5))
prod_month_rev_sorted['change_lakh'] = prod_month_rev_sorted['change'] / 1e5
prod_month_rev_sorted['change_lakh'].head(10).plot(kind='bar', ax=ax, color='teal')
ax.set_title(f"Top 10 Products by Revenue Drop in {main_region} ({biggest_drop_cat}, Sep vs Aug 2026)")
ax.set_xlabel("Product")
ax.set_ylabel("Revenue Change (Rs lakh)")
plt.tight_layout()
plt.savefig("top_products_revenue_drop_main_region.png", dpi=120)
plt.close()

# 13. SUMMARY block
print("\n" + "="*60)
print("SUMMARY")
print("="*60)
print(f"Category with biggest revenue drop: {biggest_drop_cat}")
print(f"  Aug 2026 Revenue: Rs {int(biggest_drop_row['Aug_revenue']):,} ({biggest_drop_row['Aug_revenue']/1e5:.2f} L)")
print(f"  Sep 2026 Revenue: Rs {int(biggest_drop_row['Sep_revenue']):,} ({biggest_drop_row['Sep_revenue']/1e5:.2f} L)")
print(f"  Change: Rs {int(biggest_drop_row['change']):,} ({biggest_drop_row['change']/1e5:.2f} L)")
print(f"  % Change: {biggest_drop_row['pct_change']:.2f}%")
print(f"Region causing most of the drop: {main_region}")
print(f"  Region's change: Rs {int(main_region_row['change']):,} ({main_region_row['change']/1e5:.2f} L)")
print(f"  Share of total drop: {main_region_row['share_pct']:.2f}%")
print("See PNG charts for visual breakdowns.")
